/**
 * FCA Registry — JS Merge Node v17.1 (Updated)
 *
 * Input:  TWO upstream agent inputs, merged automatically regardless of
 *         their node names — Firm Details (firm_core, firm_address,
 *         firm_permissions, firm_regulators) and Individuals & CF
 *         (firm_individuals, firm_cf_pages). Also still works unchanged
 *         with a single combined upstream agent.
 *
 * Output: Single KYC schema object assigned to outputData.
 *         All enum fields are validated — invalid values are set to null.
 */

// ─────────────────────────────────────────────────────────────────────────────
// 1. READ & PARSE UPSTREAM INPUT
// ─────────────────────────────────────────────────────────────────────────────
var row = {};
var upstreamReasoning = [];
var inputKeys = Object.keys(inputs || {});

for (var ii = 0; ii < inputKeys.length; ii++) {
  var connectedVal = inputs[inputKeys[ii]];
  var item = Array.isArray(connectedVal) ? connectedVal[0] : connectedVal;
  if (!item || typeof item !== "object") continue;

  var itemKeys = Object.keys(item);
  for (var ki = 0; ki < itemKeys.length; ki++) {
    var key = itemKeys[ki];
    if (key === "_reasoning") {
      if (item[key]) upstreamReasoning.push(String(item[key] && typeof item[key] === "object" && "value" in item[key] ? item[key].value : item[key]));
      continue;
    }
    if (key === "frn" && row.frn) continue; // first input's frn wins; both agents should agree
    row[key] = item[key];
  }
}

// Every field from the agent is wrapped in a confidence envelope
function unwrap(field) {
  if (field === null || field === undefined) return null;
  if (typeof field === "object" && "value" in field) return field.value;
  return field;
}

function safeParse(val) {
  if (val !== null && typeof val === "object") return val;
  if (typeof val === "string" && val !== "") {
    try { return JSON.parse(val); } catch(e) { return null; }
  }
  return null;
}

function unwrapAndParse(field) {
  return safeParse(unwrap(field));
}

var frn        = String(unwrap(row.frn) || "").trim();
var coreResp   = unwrapAndParse(row.firm_core);
var addrResp   = unwrapAndParse(row.firm_address);
var permResp   = unwrapAndParse(row.firm_permissions);
var indivsResp = unwrapAndParse(row.firm_individuals);
var cfPages    = unwrapAndParse(row.firm_cf_pages);
var regResp    = unwrapAndParse(row.firm_regulators); 

// ─────────────────────────────────────────────────────────────────────────────
// 2. FULL ENUM SETS 
// ─────────────────────────────────────────────────────────────────────────────
var VALID_STATUSES = { "active": 1, "inactive": 1 };

var VALID_OFFICER_TYPES = {
  "Chief Executive Officer": 1, "President": 1, "Chief Financial Officer": 1,
  "Treasurer": 1, "Chief Operating Officer": 1, "General Partner": 1,
  "Board Director": 1, "Board Chairman": 1, "Chief Compliance Officer": 1,
  "Chief Investment Officer": 1, "Chief Risk Officer": 1, "Executive Director": 1, 
  "Director": 1, "Manager": 1, "Managing Director": 1, "Managing General Partner": 1,
  "Managing Member": 1, "Designated Member": 1, "Secretary": 1,
  "Senior Vice President": 1, "Vice President": 1
};

var VALID_REGULATORS = {
  "Financial Conduct Authority": 1,
  "Prudential Regulation Authority": 1,
  "Australian Securities and Investment Commission (ASIC)": 1,
  "Australian Prudential Regulatory Authority (APRA)": 1,
  "Financial Market Authority": 1,
  "Commission Bancaire, Financière et des Assurances - Banking Finance and Insurance Commission (BFIC)": 1,
  "Comissão do Valores Mobiliários - Securities and Exchange Commission of Brazil (CVM)": 1,
  "Superintendência de Seguros Privados (Susep)": 1,
  "Office of the Superintendent of Financial Institutions Canada": 1,
  "Finanstilsynet - Danish Financial Supervisory Authority": 1,
  "Finnish Financial Supervision Authority (FIN-FSA)": 1,
  "Insurance Supervisory Authority (ISA)": 1,
  "Banque de France/Commision Bancaire": 1,
  "Autorité des Marchés Financiers (AMF)": 1,
  "Autorité de Contrôle des Assurances et des Mutuelles": 1,
  "Bundesanstalt fur Finanzdienstleistungs-aufsicht (BaFin)": 1,
  "Bank of Greece": 1,
  "Hellenic Republic Capital Market Commission": 1,
  "Guernsey Financial Services Commission": 1,
  "Hong Kong Monetary Authority": 1,
  "Securities and Futures Commission": 1,
  "Office of the Commissioner of Insurance": 1,
  "Fjármálaeftirlitiđ - Financial Supervisory Authority, Iceland (FME)": 1,
  "Central Bank and Financial Services Authority of Ireland": 1,
  "Financial Supervision Commission (FSM)": 1,
  "Banca d'Italia Eurosistema": 1,
  "Commissione Nazionale per le Società e la Borsa (Consob)": 1,
  "Istituto per la Vigilanza sulle Assicurazioni Private e di Interesse Collecttivo (ISVAP)": 1,
  "Financial Services Agency": 1,
  "Jersey Financial Services Corp. (JFSC)": 1,
  "Commission de Surveillance du Secteur Financier (CSSF)": 1,
  "Banka Negara Malaysia - Central Bank of Malaysia": 1,
  "De Nederlandsche Bank Eurosysteem": 1,
  "Netherlands Authority for Financial Markets (AFM)": 1,
  "Reserve Bank of New Zealand": 1,
  "Securities Commission of New Zealand": 1,
  "Kredittilsynet - Financial Supervisory Authority of Norway": 1,
  "Banco de Portugal": 1,
  "Comissão do Mercado de Valores Mobiliários - Portugese Securities Market Commission (CMVM)": 1,
  "Instituto de Seguros de Portugal - Portugese Insurance Institute (ISP)": 1,
  "Monetary Authority of Singapore": 1,
  "Banco de España Eurosistema": 1,
  "Comisión Nacional del Mercado de Valores": 1,
  "Dirección General de Seguros y Fondos de Pensiones (DGSFP)": 1,
  "Finansinspektionen - Swedish Financial Supervisory Authority": 1,
  "Commission fédérale des banques - Swiss Federal Banking Commission (SFBC)": 1,
  "Financial Services Authority (FSA)": 1,
  "Federal Reserve Board": 1,
  "Office of the Comptroller of the Currency (OCC)": 1,
  "Office of Thrift Supervision (OTS)": 1,
  "Federal Deposit Insurance Corp. (FDIC)": 1,
  "Federal Housing Finance Board (FHFB)": 1,
  "National Credit Union Administration (NCUA)": 1,
  "Commodity Futures Trading Commission (CFTC)": 1,
  "National Futures Association (NFA)": 1,
  "National Association of Securities Dealers (NASD)": 1,
  "U.S. Securities and Exchange Commission (SEC)": 1,
  "Consumer Financial Protection Bureau (CFPB)": 1,
  "Alabama State Banking Department": 1, "Alaska Division of Banking and Securities": 1,
  "Arizona Department of Financial Institutions": 1, "Arkansas State Bank Department": 1,
  "California Department of Financial Protection and Innovation (DFPI)": 1, "Colorado Division of Banking": 1,
  "Connecticut Department of Banking": 1, "Delaware Office of the State Bank Commissioner": 1,
  "Florida Office of Financial Regulation": 1, "Georgia Department of Banking and Finance": 1,
  "Hawaii Division of Financial Institutions": 1, "Idaho Department of Finance": 1,
  "Illinois Division of Banking": 1, "Indiana Department of Financial Institutions": 1,
  "Iowa Division of Banking": 1, "Kansas Office of the State Bank Commissioner": 1,
  "Kentucky Department of Financial Institutions": 1, "Louisiana Office of Financial Institutions": 1,
  "Maine Bureau of Financial Institutions": 1, "Maryland Office of the Commissioner of Financial Regulation": 1,
  "Massachusetts Division of Banks": 1, "Michigan Department of Insurance and Financial Services": 1,
  "Minnesota Department of Commerce": 1, "Mississippi Department of Banking and Consumer Finance": 1,
  "Missouri Division of Finance": 1, "Montana Division of Banking and Financial Institutions": 1,
  "Nebraska Department of Banking and Finance": 1, "Nevada Financial Institutions Division": 1,
  "New Hampshire Banking Department": 1, "New Jersey Department of Banking and Insurance": 1,
  "New Mexico Financial Institutions Division": 1, "New York State Department of Financial Services": 1,
  "North Carolina Office of the Commissioner of Banks": 1, "North Dakota Department of Financial Institutions": 1,
  "Ohio Division of Financial Institutions": 1, "Oklahoma State Banking Department": 1,
  "Oregon Division of Financial Regulation": 1, "Pennsylvania Department of Banking and Securities": 1,
  "Rhode Island Department of Business Regulation": 1, "South Carolina State Board of Financial Institutions": 1,
  "South Dakota Division of Banking": 1, "Tennessee Department of Financial Institutions": 1,
  "Texas Department of Banking": 1, "Utah Department of Financial Institutions": 1,
  "Vermont Department of Financial Regulation": 1, "Virginia Bureau of Financial Institutions": 1,
  "Washington Department of Financial Institutions": 1, "West Virginia Division of Financial Institutions": 1,
  "Wisconsin Department of Financial Institutions": 1, "Wyoming Division of Banking": 1
};

// ─────────────────────────────────────────────────────────────────────────────
// 2b. TOLERANT ENUM MATCHING
// ─────────────────────────────────────────────────────────────────────────────
function normalizeForMatch(str) {
  if (!str) return "";
  return String(str)
    .normalize("NFKC")
    .replace(/[\u2018\u2019\u02BC]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .replace(/[\u2013\u2014]/g, "-")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim()
    .toLowerCase();
}

function buildNormalizedLookup(enumSet) {
  var lookup = {};
  var keys = Object.keys(enumSet);
  for (var nli = 0; nli < keys.length; nli++) lookup[normalizeForMatch(keys[nli])] = keys[nli];
  return lookup;
}

var NORMALIZED_STATUSES      = buildNormalizedLookup(VALID_STATUSES);
var NORMALIZED_OFFICER_TYPES = buildNormalizedLookup(VALID_OFFICER_TYPES);
var NORMALIZED_REGULATORS    = buildNormalizedLookup(VALID_REGULATORS);

var NORMALIZED_LOOKUPS = [
  { enumSet: VALID_STATUSES,      normalized: NORMALIZED_STATUSES },
  { enumSet: VALID_OFFICER_TYPES, normalized: NORMALIZED_OFFICER_TYPES },
  { enumSet: VALID_REGULATORS,    normalized: NORMALIZED_REGULATORS }
];

function validateEnum(value, enumSet) {
  if (value === null || value === undefined) return null;
  if (enumSet[value]) return value;
  var normalizedValue = normalizeForMatch(value);
  if (!normalizedValue) return null;
  for (var nlk = 0; nlk < NORMALIZED_LOOKUPS.length; nlk++) {
    if (NORMALIZED_LOOKUPS[nlk].enumSet === enumSet) {
      return NORMALIZED_LOOKUPS[nlk].normalized[normalizedValue] || null;
    }
  }
  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. MAPPING TABLES
// ─────────────────────────────────────────────────────────────────────────────
var STATUS_MAP = {
  "Authorised":   "active",
  "Registered":   "active",
  "Unauthorised": "inactive",
  "Cancelled":    "inactive",
  "See full details": "active",
  "No longer authorised": "inactive", // Added Fix
  "Lapsed": "inactive"                // Added Fix
};

var OFFICER_ROLE_MAP = {
  "SMF1":  "Chief Executive Officer",
  "SMF9":  "Board Chairman",
  "SMF2":  "Chief Financial Officer",
  "SMF3":  "Executive Director",
  "SMF4":  "Chief Risk Officer",
  "SMF24": "Chief Operating Officer",
  "SMF16": "Chief Compliance Officer",
  "SMF10": "Board Director",
  "SMF11": "Board Director",
  "SMF12": "Board Director",
  "SMF14": "Board Director",
  "CF3":   "Director",
  "CF1":   "Director",
  "CF2":   "Board Director"
};

var ROLE_SENIORITY  = [
  "SMF1","SMF9","SMF2","SMF3","SMF4","SMF24","SMF16",
  "SMF10","SMF11","SMF12","SMF14","CF3","CF1","CF2"
];

var CONTROLLER_CODE = "SMF9";

var REGULATOR_NAME_MAP = {
  "FCA": "Financial Conduct Authority",
  "PRA": "Prudential Regulation Authority",
  "Financial Services Authority": "Financial Services Authority (FSA)"
};

// ─────────────────────────────────────────────────────────────────────────────
// 4. PARSE FIRM CORE
// ─────────────────────────────────────────────────────────────────────────────
var firm;
if (coreResp && Array.isArray(coreResp.Data) && coreResp.Data.length > 0) {
  firm = coreResp.Data[0];
} else if (coreResp && typeof coreResp === "object" && (coreResp["Organisation Name"] || coreResp["FRN"])) {
  firm = coreResp;
} else {
  firm = {};
}

var entityName = firm["Organisation Name"] || null;
var rawStatus  = firm["Status"]            || null;
var rawBizType = firm["Business Type"]     || null;

var entityStatus = validateEnum(STATUS_MAP[rawStatus] || null, VALID_STATUSES);
var firmFound = entityName !== null;

// ─────────────────────────────────────────────────────────────────────────────
// 4b. PARSE REGULATOR(S)
// ─────────────────────────────────────────────────────────────────────────────
var regulatorSet  = {};
var regulatorList = [];

function addRegulator(rawName) {
  if (!rawName) return;
  var mapped    = REGULATOR_NAME_MAP[rawName] || rawName;
  var validated = validateEnum(mapped, VALID_REGULATORS);
  if (validated && !regulatorSet[validated]) {
    regulatorSet[validated] = 1;
    regulatorList.push(validated);
  }
}

var regulatorRecordsFound = false;

// Updated to handle Agent casing/nesting hallucinations
function extractRegulatorEntries(parsed) {
  if (!parsed) return [];
  if (Array.isArray(parsed.Data)) return parsed.Data;
  if (Array.isArray(parsed.regulators)) return parsed.regulators;
  if (Array.isArray(parsed.Regulators)) return parsed.Regulators; 
  if (Array.isArray(parsed["Current Regulators"])) return parsed["Current Regulators"];
  if (Array.isArray(parsed)) return parsed;
  if (parsed["Regulator Name"] || parsed["Name"]) return [parsed];
  return [];
}

var regulatorEntries = extractRegulatorEntries(regResp);

if (regulatorEntries.length > 0) {
  regulatorRecordsFound = true;
  for (var rgi = 0; rgi < regulatorEntries.length; rgi++) {
    var regEntry  = regulatorEntries[rgi];
    var hasEnded  = regEntry["Termination Date"] || regEntry["End Date"] || regEntry["EndDate"];
    if (hasEnded) continue;
    addRegulator(regEntry["Regulator Name"] || regEntry["Name"]);
  }
} else if (firmFound && entityStatus === "active") {
  addRegulator("Financial Conduct Authority");
}

var regulatorObjects = [];
for (var rli = 0; rli < regulatorList.length; rli++) {
  regulatorObjects.push({ regulator_name: regulatorList[rli] });
}

var entityRegulatorLog = regulatorList.length > 0 ? regulatorList.join("; ") : null;

// ─────────────────────────────────────────────────────────────────────────────
// 5. PARSE ADDRESS
// ─────────────────────────────────────────────────────────────────────────────
var addrRecords = [];
if (addrResp && Array.isArray(addrResp.Data)) {
  addrRecords = addrResp.Data;
} else if (addrResp && typeof addrResp === "object") {
  var addrTypeKeys = Object.keys(addrResp);
  for (var ati = 0; ati < addrTypeKeys.length; ati++) {
    var addrTypeKey = addrTypeKeys[ati];
    var addrVal = addrResp[addrTypeKey];
    if (addrVal && typeof addrVal === "object" && !Array.isArray(addrVal)) {
      var normalized = {};
      var avKeys = Object.keys(addrVal);
      for (var avi = 0; avi < avKeys.length; avi++) normalized[avKeys[avi]] = addrVal[avKeys[avi]];
      normalized["Address Type"] = addrTypeKey;
      addrRecords.push(normalized);
    }
  }
}

var ppob = null;
for (var i = 0; i < addrRecords.length; i++) {
  if (addrRecords[i]["Address Type"] === "Principal Place of Business") {
    ppob = addrRecords[i];
    break;
  }
}
if (!ppob && addrRecords.length > 0) ppob = addrRecords[0];
ppob = ppob || {};

function toTitleCase(str) {
  if (!str) return null;
  return str.replace(/\w\S*/g, function(w) {
    return w.charAt(0).toUpperCase() + w.substr(1).toLowerCase();
  });
}

var countryRaw    = ppob["Country"] || null;
var countryTitled = toTitleCase(countryRaw);

var addressParts = [
  ppob["Address Line 1"],
  ppob["Address Line 2"],
  ppob["Address Line 3"] || ppob["Address LIne 3"],
  ppob["Address Line 4"],
  ppob["Town"],
  ppob["County"],
  ppob["Postcode"],
  countryTitled
];

var principalPlaceOfBusiness = addressParts
  .filter(function(part) { return part && String(part).trim() !== ""; })
  .join(", ");
principalPlaceOfBusiness = principalPlaceOfBusiness || null;

var rawSite = ppob["Website Address"] || ppob["Website"] || null;
var website = rawSite ? rawSite.replace(/^https?:\/\//i, "").replace(/\/$/, "") : null;

// ─────────────────────────────────────────────────────────────────────────────
// 6. PARSE PERMISSIONS
// ─────────────────────────────────────────────────────────────────────────────
var PERM_EXCLUDE = {
  "CBTL Status":          1, "CBTL Effective Date":  1, "PSD Status":           1,
  "PSD Effective Date":   1, "EMD Status":           1, "EMD Effective Date":   1,
  "MLR Status":           1, "MLR Effective Date":   1, "CBTL arranger Status": 1,
  "CBTL advisor Status":  1, "Acting as a CBTL arranger": 1, "Acting as a CBTL advisor":  1
};

var activityType = null;
var activityKeys = [];
if (permResp && permResp.Data && typeof permResp.Data === "object" && !Array.isArray(permResp.Data)) {
  var allPermKeys = Object.keys(permResp.Data);
  for (var a = 0; a < allPermKeys.length; a++) {
    if (!PERM_EXCLUDE[allPermKeys[a]]) activityKeys.push(allPermKeys[a]);
  }
} else if (permResp && typeof permResp === "object" && !Array.isArray(permResp)) {
  var looksLikeEnvelope = permResp.Status !== undefined || permResp.ResultInfo !== undefined || permResp.Message !== undefined;
  if (!looksLikeEnvelope) {
    var topPermKeys = Object.keys(permResp);
    var permArrayKey = null;
    for (var pk = 0; pk < topPermKeys.length; pk++) {
      var pv = permResp[topPermKeys[pk]];
      if (Array.isArray(pv) && pv.length > 0 && typeof pv[0] === "string") {
        permArrayKey = topPermKeys[pk];
        break;
      }
    }
    if (permArrayKey) {
      activityKeys = permResp[permArrayKey].slice();
    } else {
      for (var c = 0; c < topPermKeys.length; c++) {
        if (!PERM_EXCLUDE[topPermKeys[c]]) activityKeys.push(topPermKeys[c]);
      }
    }
  }
}

if (activityKeys.length > 0) {
  activityType = activityKeys.join("; ");
}

// ─────────────────────────────────────────────────────────────────────────────
// 7. PARSE CF INDIVIDUALS
// ─────────────────────────────────────────────────────────────────────────────
function extractRoleCode(key) {
  var m = key.match(/\)\s*((?:SMF|CF)\d+)/i);
  return m ? m[1].toUpperCase() : null;
}

function extractIRN(url) {
  if (!url) return null;
  var parts = url.split("/");
  return parts[parts.length - 1] || null;
}

function extractFlatRoleSample(parsed) {
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return null;
  var sampleKeys = ["current_roles_sample", "roles_sample", "current_roles", "sample"];
  for (var sk = 0; sk < sampleKeys.length; sk++) {
    if (Array.isArray(parsed[sampleKeys[sk]])) return parsed[sampleKeys[sk]];
  }
  return null;
}

function extractRoleCodeFlat(roleStr) {
  if (!roleStr) return null;
  var m = String(roleStr).match(/^\s*((?:SMF|CF)\d+)/i);
  return m ? m[1].toUpperCase() : null;
}

function extractCurrentRecords(page) {
  if (!page || typeof page !== "object") return null;
  var merged = null;
  function merge(obj) {
    if (!obj || typeof obj !== "object") return;
    if (!merged) merged = {};
    var ks = Object.keys(obj);
    for (var i = 0; i < ks.length; i++) merged[ks[i]] = obj[ks[i]];
  }

  if (page.current_records && typeof page.current_records === "object") {
    merge(page.current_records);
  }
  if (Array.isArray(page.Data)) {
    for (var d = 0; d < page.Data.length; d++) {
      var entry = page.Data[d];
      if (entry && typeof entry === "object" && entry.Current && typeof entry.Current === "object") {
        merge(entry.Current);
      }
    }
  } else if (page.Data && typeof page.Data === "object" && page.Data.Current && typeof page.Data.Current === "object") {
    merge(page.Data.Current);
  }
  if (page.Current && typeof page.Current === "object") {
    merge(page.Current);
  }
  return merged;
}

var byIRN = {};
var cfShape = "none";
var flatSample = extractFlatRoleSample(cfPages);

if (flatSample) {
  cfShape = "sample(" + flatSample.length + ")";
  for (var fi = 0; fi < flatSample.length; fi++) {
    var sampleEntry = flatSample[fi];
    if (!sampleEntry || typeof sampleEntry !== "object") continue;
    var roleStr  = sampleEntry.role || sampleEntry.Role || sampleEntry["Role Name"] || null;
    var roleCode = extractRoleCodeFlat(roleStr);
    var indName  = sampleEntry.individual || sampleEntry.Individual || sampleEntry["Individual Name"] || null;
    var irn      = sampleEntry.id || sampleEntry.IRN || sampleEntry.irn || indName;

    if (!indName || !roleCode) continue;
    if (!byIRN[irn]) { byIRN[irn] = { name: indName, codes: [] }; }
    if (byIRN[irn].codes.indexOf(roleCode) === -1) { byIRN[irn].codes.push(roleCode); }
  }
} else if (Array.isArray(cfPages)) {
  cfShape = "pages(" + cfPages.length + ")";
  for (var p = 0; p < cfPages.length; p++) {
    var page = unwrapAndParse(cfPages[p]);
    var current = extractCurrentRecords(page);
    if (!current) continue;
    var roleKeys = Object.keys(current);
    for (var k = 0; k < roleKeys.length; k++) {
      var roleKey   = roleKeys[k];
      var roleEntry = current[roleKey];
      var roleCode  = extractRoleCode(roleKey);
      var indName   = roleEntry["Individual Name"] || null;
      var irn       = extractIRN(roleEntry["URL"]) || indName;

      if (!indName || !roleCode) continue;
      if (!byIRN[irn]) { byIRN[irn] = { name: indName, codes: [] }; }
      if (byIRN[irn].codes.indexOf(roleCode) === -1) { byIRN[irn].codes.push(roleCode); }
    }
  }
}

var officers    = [];
var controllers = [];
var irnKeys     = Object.keys(byIRN);

for (var j = 0; j < irnKeys.length; j++) {
  var person  = byIRN[irnKeys[j]];
  var codes   = person.codes;

  if (codes.indexOf(CONTROLLER_CODE) !== -1) {
    controllers.push({ key_controller_name: person.name, key_controller_address: null });
  }

  var topCode = null;
  for (var s = 0; s < ROLE_SENIORITY.length; s++) {
    if (codes.indexOf(ROLE_SENIORITY[s]) !== -1) {
      topCode = ROLE_SENIORITY[s];
      break;
    }
  }

  if (topCode) {
    var mappedType    = OFFICER_ROLE_MAP[topCode] || null;
    var validatedType = validateEnum(mappedType, VALID_OFFICER_TYPES);
    if (validatedType) {
      officers.push({ officer_name: person.name, officer_address: null, officer_type: validatedType });
    }
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 8. ASSEMBLE OUTPUT
// ─────────────────────────────────────────────────────────────────────────────
var log = [
  "frn=" + frn,
  "upstream_inputs=" + inputKeys.length,
  "firm_found=" + firmFound,
  "status_raw=" + rawStatus + " status_mapped=" + entityStatus,
  "biztype_raw=" + rawBizType,
  "country_raw=" + countryRaw + " country_titled=" + countryTitled,
  "ppob_address=" + (principalPlaceOfBusiness || "null"),
  "regulators=" + (entityRegulatorLog || "null") + " (source=" + (regulatorRecordsFound ? "live" : "fallback") + ")",
  "activities=" + (activityType || "null"),
  "indivs_endpoint=" + (indivsResp ? "ok" : "null") + " cf_shape=" + cfShape,
  "individuals=" + irnKeys.length,
  "officers=" + officers.length + " controllers=" + controllers.length,
  "upstream_reasoning=[" + upstreamReasoning.join("] [") + "]"
];

outputData = {
  entity_name:                        entityName,
  entity_status:                      firmFound ? entityStatus : null,
  entity_principal_place_of_business: firmFound ? principalPlaceOfBusiness : null,
  entity_registration_number:         frn,
  entity_regulator:                   firmFound ? regulatorObjects : [],
  entity_source_url:                  firmFound ? "https://register.fca.org.uk/s/firm?id=" + frn : null,
  entity_activity_type:               firmFound ? activityType : null,
  entity_website_address:             firmFound ? website      : null,
  corporate_officer:                  officers,
  key_controller:                     controllers,
  _reasoning:                         log.join(" | ")
};

/**
 * The 'inputs' object contains all upstream node outputs, keyed by alias.
 * The 'env' object contains project environment variables (read-only).
 *
 * INPUT FORMATS:
 *   Tabular nodes  →  inputs['alias'] is an Array of row objects
 *     Example: inputs['sales_data'] = [{ region: 'US', amount: 100 }, ...]
 *
 *   JSON object nodes  →  inputs['alias'] is a parsed JavaScript value
 *     Example: inputs['api_response'] = { status: 'ok', results: [...] }
 *
 * ENVIRONMENT:
